    chatWindow.prototype.findSortedIndex = function (array, value) {
        var low = 0;
        var high = array.length;
        while (low < high) {
            var mid = (low + high) >>> 1;
            if (array[mid] < value)
                low = mid + 1;
            else
                high = mid;
        }
        return low;
    };
