    FindlySDK.prototype.getFacetsAsArray = function (facetsObj) {
        var _self = this;
        var facets = [];
        if (facetsObj) {
            Object.keys(facetsObj).forEach(function (facet) {
                facets.push({ key: facet, value: facetsObj[facet] });
            });
        }
        return facets;
    };
