    FindlySDK.prototype.bindSocketEvents = function () {
        var _self = this;
        _self.bot.on("message", function (message) {
            // debugger;
            // if (me.popupOpened === true) {
            //     $('.kore-auth-popup .close-popup').trigger("click");
            // }
            var tempData = JSON.parse(message.data);
            if (tempData.from === "bot" && tempData.type === "bot_response") {
                if ((tempData || {}).message &&
                    (tempData || {}).message[0].component.payload) {
                    if (tempData.message[0].cInfo) {
                        tempData.message[0].component.payload.cInfo =
                            tempData.message[0].cInfo;
                    }
                    _self.handleSearchRes(tempData.message[0].component.payload);
                    if ($("body").hasClass("top-down")) {
                        if (((tempData.message[0].component.payload || {}).template || {})
                            .originalQuery) {
                            if ($("#conversation-container").is(":visible")) {
                                $("#search").val(((tempData.message[0].component.payload || {}).template || {})
                                    .originalQuery);
                            }
                            else {
                                $(".top-down-suggestion").val($(".searcj-top-down").val());
                                $("#live-search-result-box").hide();
                            }
                            $("#conversation-container").hide();
                            $("#action-title").empty();
                            $("#searchChatContainer").empty();
                            $(".skelton-load-img").hide();
                        }
                    }
                }
            }
            else if (tempData.from === "self" && tempData.type === "user_message") {
                var tempmsg = tempData.message;
                var msgData = {};
                if (tempmsg &&
                    tempmsg.attachments &&
                    tempmsg.attachments[0] &&
                    tempmsg.attachments[0].fileId) {
                    msgData = {
                        type: "currentUser",
                        message: [
                            {
                                type: "text",
                                cInfo: { body: tempmsg.body, attachments: tempmsg.attachments },
                                clientMessageId: tempData.id,
                            },
                        ],
                        createdOn: tempData.id,
                    };
                }
                else {
                    msgData = {
                        type: "currentUser",
                        message: [
                            {
                                type: "text",
                                cInfo: { body: tempmsg.body },
                                clientMessageId: tempData.id,
                            },
                        ],
                        createdOn: tempData.id,
                    };
                }
                // me.renderMessage(msgData);
            }
            if (tempData.type === "appInvalidNotification") {
                setTimeout(function () {
                    $(".trainWarningDiv").addClass("showMsg");
                }, 2000);
            }
            // setTimeout(function () {
            //   $('.typingIndicatorContent').css('display', 'none');
            // }, 300);
        });
    };
