    //Template New Approach
    FindlySDK.prototype.designTemplateConfig = function (config, customConfig) {
        var _self = this;
        _self.maxSearchResultsAllowed = config.maxResultsAllowed;
        var conditions = [];
        if (config.groupResults) {
            conditions = config.groupSetting.conditions;
        }
        conditions.push({
            fieldValue: "defaultTemplate",
            template: config.defaultTemplate,
        });
        conditions.forEach(function (condition) {
            var template = condition.template || {};
            // writing conditions only for StructuredData
            if (template && template.layout) {
                _self[condition.fieldValue + "Config"][config.interface + "Interface"] =
                    template;
                if (template.layout && template.layout.layoutType) {
                    _self[condition.fieldValue + "Config"][config.interface + "Interface"].layout.templateType = template.type;
                    _self[condition.fieldValue + "Config"][config.interface + "Interface"].layout.template = "";
                    _self[condition.fieldValue + "Config"][config.interface + "Interface"].layout.maxSearchResultsAllowed = 5;
                    _self[condition.fieldValue + "Config"][config.interface + "Interface"].layout.layoutType = template.layout.layoutType;
                    _self[condition.fieldValue + "Config"][config.interface + "Interface"].layout.textAlignment = template.layout.textAlignment;
                    _self[condition.fieldValue + "Config"][config.interface + "Interface"].layout.listType = template.layout.listType;
                    _self[condition.fieldValue + "Config"][config.interface + "Interface"].layout.isClickable = template.layout.isClickable;
                    _self[condition.fieldValue + "Config"][config.interface + "Interface"].layout.behaviour = template.layout.behaviour;
                    _self[condition.fieldValue + "Config"][config.interface + "Interface"].layout.renderTitle = template.layout.renderTitle;
                    _self[condition.fieldValue + "Config"][config.interface + "Interface"].layout.title = template.layout.title;
                    _self[condition.fieldValue + "Config"][config.interface + "Interface"].mapping = template.mapping;
                    _self[condition.fieldValue + "Config"][config.interface + "Interface"].groupResults =
                        condition.fieldValue == "defaultTemplate"
                            ? false
                            : config.groupResults;
                    _self[condition.fieldValue + "Config"][config.interface + "Interface"].fieldName =
                        condition.fieldValue == "defaultTemplate"
                            ? ""
                            : config.groupSetting.fieldName;
                }
            }
            else {
                // need to handle if no template is coming from AJAX response.
                _self[condition.fieldValue + "Config"][config.interface + "Interface"].layout.templateType = "list";
                _self[condition.fieldValue + "Config"][config.interface + "Interface"].layout.layoutType = "l1";
                _self[condition.fieldValue + "Config"][config.interface + "Interface"].layout.template = "";
                _self[condition.fieldValue + "Config"][config.interface + "Interface"].layout.maxSearchResultsAllowed = _self.maxSearchResultsAllowed;
                _self[condition.fieldValue + "Config"][config.interface + "Interface"].layout.behaviour = "webpage";
                _self[condition.fieldValue + "Config"][config.interface + "Interface"].layout.isClickable = false;
                _self[condition.fieldValue + "Config"][config.interface + "Interface"].layout.listType = "classic";
                _self[condition.fieldValue + "Config"][config.interface + "Interface"].layout.renderTitle = false;
            }
        });
    };
