    FindlySDK.prototype.bindPlaceholderStyle = function (config) {
        var canvas = document.createElement("canvas");
        var ctx = canvas.getContext("2d");
        ctx.font = "14px 'Inter', sans-serif";
        var width = ctx.measureText(config.searchConfig.buttonText).width;
        if (config.searchConfig.buttonPlacementPosition == "inside") {
            var rightPosition = 70 + 31 + 23;
            rightPosition = rightPosition + width + 1;
            $("body").append("<style>.cancel-search {right:" +
                rightPosition +
                "px !important;}</style>");
        }
        else {
            $("body").append("<style>.cancel-search {right: 72px !important;}</style>");
            if (config.searchConfig.buttonPlacementPosition == "outside") {
                var rightPosition = 812;
                // if(config.searchConfig.buttonText.length==1){
                //   rightPosition = 12;
                // }
                // if(config.searchConfig.buttonText.length==2){
                //   rightPosition = 6;
                // }
                // if(config.searchConfig.buttonText.length==3){
                //   rightPosition = -6;
                // }
                // if(config.searchConfig.buttonText.length==4){
                //   rightPosition = -16;
                // }
                // if(config.searchConfig.buttonText.length==5){
                //   rightPosition = -26;
                // }
                // if(config.searchConfig.buttonText.length==6){
                //   rightPosition = -32;
                // }
                $("body").append("<style>.submit-button-outside {left: " +
                    rightPosition +
                    "px !important;}</style>");
            }
        }
        $("body").append("<style>.cancel-search .cross {color:" +
            config.searchConfig.searchBarPlaceholderTextColor +
            "!important;}</style>");
    };
    ;
    FindlySDK.prototype.appendActionsContainerForBottomUp = function (from) {
        var actionsPosition = "bottom";
        if (searchConfigurationCopy && searchConfigurationCopy.botConfig) {
            actionsPosition =
                searchConfigurationCopy.botConfig.botActionResultsExperience;
        }
        var actionParentContainer;
        if (from && from == "search") {
            actionParentContainer = "<div class=\"actions-search-container\"></div>";
            if (actionsPosition === "top") {
                $(".search-data-container").last().before(actionParentContainer);
            }
            else {
                $(".bottom-search-show-all-results").last().before(actionParentContainer);
            }
        }
        else {
            actionParentContainer = "<div id=\"actions-full-search-container\" class=\"quick-actions-full-search-container actions-full-search-container\"></div>";
            if (actionsPosition === "top") {
                $(".data-body-sec").prepend(actionParentContainer);
            }
            else {
                $(".custom-add-result-container").after(actionParentContainer);
            }
        }
    };
    ;
    FindlySDK.prototype.frequentlySearchedRecentTextClickEvent = function () {
        var _self = this;
        $("#frequently-searched-box")
            .off("click", ".recentText")
            .on("click", ".recentText", function (e) {
            var recentText = $(e.currentTarget).attr("id");
            $("#search").val(recentText);
            $("#suggestion").val(recentText);
            $(".top-down-suggestion").val(recentText);
            $(".search-top-down").val(recentText);
            $("#frequently-searched-box").hide();
            if (_self.isDev) {
                if ($(".top-down-search-background-div")) {
                    $(".top-down-search-background-div").addClass("if-full-results");
                    $(".top-down-wrapper").addClass("top-down-wrapper-height");
                }
            }
            //     e.preventDefault();
            // e.stopImmediatePropagation();
            _self.vars.searchObject.searchText = recentText;
            _self.vars.showingMatchedResults = true;
            _self.searchFacetsList([]);
            // _self.invokeSearch();
            var e = $.Event("keydown", { which: 13 });
            $("#search").trigger(e);
            // _self.pubSub.publish('sa-search-facets', _self.vars.searchFacetFilters);
            //$('#search').trigger("keyup");
            setTimeout(function () {
                //   var e = $.Event( "keydown", { which: 13 } );
                // $('#search').trigger(e);
                // $('#loaderDIV').show();
                $(".all-result-container").show();
                //top-down-searc-facets active -start//
                _self.pubSub.publish("facet-selected", {
                    selectedFacet: "all results",
                });
                //top-down-search-facets active -end//
                $("#live-search-result-box").hide();
                $("#frequently-searched-box").hide();
                $("#loaderDIV").hide();
            }, 600);
            if ($("body").hasClass("top-down")
                ? $(".search-top-down").val()
                : $(".bottom-up-search").val()) {
                $(".cancel-search").show();
            }
            else {
                $(".cancel-search").hide();
                $("#live-search-result-box").hide();
            }
        });
    };
