    FindlySDK.prototype.unlockBot = function () {
        var _self = this;
        var payload = {
            userId: _self.API.uuid,
            streamId: _self.API.streamId,
            lang: "en",
        };
        var url = _self.API.unlockbotUrl;
        var bearer = "bearer " + _self.bot.options.accessToken ||
            0 ||
            0;
        var headers = {};
        headers["Authorization"] = bearer;
        headers["Content-Type"] = "application/json";
        payload.userId = _self.bot.userInfo.userInfo.userId;
        payload.streamId = _self.bot.options.botInfo.taskBotId;
        payload.botInfo = _self.bot.options.botInfo;
        if (!_self.isDev) {
            if (_self.config.botOptions.assertion) {
                headers.auth = _self.config.botOptions.assertion;
            }
            payload["client"] = "sdk";
        }
        else {
            payload["client"] = "botbuilder";
        }
        payload = JSON.stringify(payload);
        return $.ajax({
            url: url,
            type: "POST",
            dataType: "json",
            headers: headers,
            data: payload,
            success: function (data) { },
            error: function (err) { },
        });
    };
