    FindlySDK.prototype.rearrangeTabsList = function (facets) {
        var _self = this;
        var rearrangeList = [];
        if (_self.vars.defaultTabsList.length) {
            var allResultObj = facets.find(function (t) { return t.key === "all results"; });
            if (allResultObj) {
                rearrangeList.push(allResultObj);
            }
            _self.vars.defaultTabsList.forEach(function (tab) {
                var facetObj = facets.find(function (t) { return t.key === tab.fieldValue; });
                if (facetObj) {
                    rearrangeList.push(facetObj);
                }
            });
        }
        else {
            rearrangeList = facets;
        }
        return rearrangeList;
    };
